&lt;p style="text-align:center"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:arial nova,arial nova_embeddedfont,arial nova_msfontservice,sans-serif"&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
