     &lt;li&gt;&lt;a href="https://nam11.safelinks.protection.outlook.com/?url=https%3A%2F%2Fcsapps.pacificpower.net%2Fsecure%2Fmy-account%2Fmanage%2Falerts&amp;amp;data=05%7C02%7Csimon.gutierrez%40pacificorp.com%7Cd4daae0f780047b8398a08dc106b1f16%7C7c1f6b10192b4a839d3281ef58325c37%7C0%7C0%7C638403299479850333%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=lSnnz3LPA1hZ00CogzYIEjDGjNY0UAXwNDekiICs0mU%3D&amp;amp;reserved=0"&gt;&lt;span style="font-family:calibri; font-size:12.0pt"&gt;Sign up to receive outage alerts&lt;/span&gt;&lt;/a&gt;&lt;span style="color:black; font-family:calibri; font-size:12.0pt"&gt;&amp;nbsp;by text,&amp;nbsp;email&amp;nbsp;or phone.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="color:black; font-family:calibri; font-size:12.0pt"&gt;Restock&amp;nbsp;your&nbsp;&lt;/span&gt;&lt;a href="https://nam11.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.pacificpower.net%2Foutages-safety%2Fstorm-emergency-preparedness.html&amp;amp;data=05%7C02%7Csimon.gutierrez%40pacificorp.com%7Cd4daae0f780047b8398a08dc106b1f16%7C7c1f6b10192b4a839d3281ef58325c37%7C0%7C0%7C638403299479850333%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=SoyrLaLxCZcCOrJV%2BgakjMQr4FjLg%2BOPNGuTEwG3ti8%3D&amp;amp;reserved=0"&gt;&lt;span style="font-family:calibri; font-size:12.0pt"&gt;outage kit&lt;/span&gt;&lt;/a&gt;&lt;span style="color:black; font-family:calibri; font-size:12.0pt"&gt;.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-family:calibri; font-size:12.0pt"&gt;Keep&nbsp;mobile devices charged so that they may be used in an emergency.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="color:black; font-family:calibri; font-size:12.0pt"&gt;Track outages, update contact&amp;nbsp;info&amp;nbsp;and do more with&amp;nbsp;our&nbsp;&lt;/span&gt;&lt;a href="https://nam11.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.pacificpower.net%2Fmy-account%2Fmobile-app.html&amp;amp;data=05%7C02%7Csimon.gutierrez%40pacificorp.com%7Cd4daae0f780047b8398a08dc106b1f16%7C7c1f6b10192b4a839d3281ef58325c37%7C0%7C0%7C638403299479850333%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=R8RTi45EHeQd40zKMTtdpfsp0MSsi1QLvYVl%2F8mGcN0%3D&amp;amp;reserved=0"&gt;&lt;span style="font-family:calibri; font-size:12.0pt"&gt;free app&lt;/span&gt;&lt;/a&gt;&lt;span style="color:black; font-family:calibri; font-size:12.0pt"&gt;.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-family:calibri; font-size:12.0pt"&gt;Text OUT to 722797 to report your outage or STAT to check status.&nbsp;&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style="margin-left:.75in"&gt;&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style="color:black"&gt;Visit&nbsp;&lt;/span&gt;&lt;a href="https://nam11.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.pacificpower.net%2Foutages-safety.html&amp;amp;data=05%7C02%7Csimon.gutierrez%40pacificorp.com%7Cd4daae0f780047b8398a08dc106b1f16%7C7c1f6b10192b4a839d3281ef58325c37%7C0%7C0%7C638403299479850333%7CUnknown%7CTWFpbGZsb3d8eyJWIjoiMC4wLjAwMDAiLCJQIjoiV2luMzIiLCJBTiI6Ik1haWwiLCJXVCI6Mn0%3D%7C3000%7C%7C%7C&amp;amp;sdata=peWVJvOmZvZAcboyeXLzVnS7fWJhMZHxFXsqqpJgN0U%3D&amp;amp;reserved=0"&gt;pacificpower.net/outages&lt;/a&gt;&lt;span style="color:black"&gt;&amp;nbsp;for restoration estimates.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;As a reminder, stay away from all downed power lines and utility lines. Even if the lines are not sparking, they could be energized and extremely dangerous.&nbsp;Customers should avoid both downed trees and powerlines as well as keep pets far away from those areas.&nbsp;&nbsp;&amp;nbsp;&lt;/p&gt;

