&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Special Guests:&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;Goats dressed in holiday attire on select dates, including opening day.&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
