&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Interactive Art:&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;Explore Mike Bennett&rsquo;s Holiday Gift Shop, brimming with art, collectibles, and cheer.&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
