&lt;div class="ListContainerWrapper SCXW18061395 BCX0" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; position: relative;"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Cultural Celebrations:&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;Traditional Las Posadas celebration, artisan markets, and wine walks throughout December.&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
