&lt;p&gt;&lt;span style="font-size:12px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="color:inherit"&gt;&lt;strong&gt;Dr. Howard is prepared to discuss:&lt;/strong&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
